parameters.command:
FLOW_PATH="/work/output/artifacts/skill-flow-hitl-quality-boolean-decision/VendorApprovalSolution/VendorApproval/VendorApproval.flow"
SKILL_DIR="/home/azureuser/projects/skills/tmp/skills/uipath-maestro-flow"

# Save registry definitions to temp files (already fetched in T1, re-saving for plan)
uip maestro flow registry get core.control.end --output json > /tmp/end_def.json
uip maestro flow registry get core.action.script --output json > /tmp/script_def.json
uip maestro flow registry get core.logic.decision --output json > /tmp/decision_def.json
uip maestro flow registry get uipath.human-in-the-loop.quick-form --output json > /tmp/hitl_def.json

# Write plan via Python to avoid shell quoting issues
python3 - << 'PYEOF'
import json, uuid

plan = {
    "ops": [
        {
            "op": "add-node",
            "id": "setVendorContext",
            "type": "core.action.script",
            "definitionFile": "/tmp/script_def.json",
            "label": "Set Vendor Context",
            "inputs": {
                "script": "return { vendorName: \"Acme Corp\", creditScore: 720 };"
            },
            "outputs": "auto"
        },
        {
            "op": "add-node",
            "id": "complianceReview",
            "type": "uipath.human-in-the-loop.quick-form",
            "definitionFile": "/tmp/hitl_def.json",
            "label": "Compliance Review",
            "inputs": {
                "schema": {
                    "schemaId": str(uuid.uuid4()),
                    "fields": [
                        {
                            "id": "vendorName",
                            "label": "Vendor Name",
                            "type": "text",
                            "direction": "input",
                            "binding": "vars.setVendorContext.output.vendorName"
                        },
                        {
                            "id": "creditScore",
                            "label": "Credit Score",
                            "type": "number",
                            "direction": "input",
                            "binding": "vars.setVendorContext.output.creditScore"
                        },
                        {
                            "id": "approved",
                            "label": "Approved",
                            "type": "boolean",
                            "direction": "output",
                            "variable": "vars.vendorApproved"
                        },
                        {
                            "id": "risk_notes",
                            "label": "Risk Notes",
                            "type": "text",
                            "direction": "output",
                            "variable": "vars.vendorRiskNotes"
                        }
                    ],
                    "outcomes": [
                        {
                            "id": "approve",
                            "name": "Approve",
                            "type": "string",
                            "isPrimary": True,
                            "action": "Continue"
                        },
                        {
                            "id": "reject",
                            "name": "Reject",
                            "type": "string",
                            "isPrimary": False,
                            "action": "End"
                        }
                    ]
                },
                "recipient": {
                    "channels": ["Email", "ActionCenter"],
                    "connections": {},
                    "assignee": {"type": "group"}
                },
                "priority": "Medium",
                "title": "Vendor Compliance Review"
            },
            "outputs": "auto"
        },
        {
            "op": "add-node",
            "id": "approvalDecision",
            "type": "core.logic.decision",
            "definitionFile": "/tmp/decision_def.json",
            "label": "Approved?",
            "inputs": {
                "expression": "$vars.complianceReview.output.approved",
                "trueLabel": "Approve",
                "falseLabel": "Reject"
            },
            "outputs": "none"
        },
        {
            "op": "add-node",
            "id": "onboardVendor",
            "type": "core.action.script",
            "definitionFile": "/tmp/script_def.json",
            "label": "Log Vendor Onboarded",
            "inputs": {
                "script": "return { message: \"Vendor onboarded\" };"
            },
            "outputs": "auto"
        },
        {
            "op": "add-node",
            "id": "rejectVendor",
            "type": "core.action.script",
            "definitionFile": "/tmp/script_def.json",
            "label": "Log Vendor Rejected",
            "inputs": {
                "script": "return { message: \"Vendor rejected\" };"
            },
            "outputs": "auto"
        },
        {
            "op": "add-node",
            "id": "endApproved",
            "type": "core.control.end",
            "definitionFile": "/tmp/end_def.json",
            "label": "End (Approved)",
            "outputs": "none"
        },
        {
            "op": "add-node",
            "id": "endRejected",
            "type": "core.control.end",
            "definitionFile": "/tmp/end_def.json",
            "label": "End (Rejected)",
            "outputs": "none"
        },
        {
            "op": "add-edge",
            "source": "start",
            "sourcePort": "output",
            "target": "setVendorContext",
            "targetPort": "input"
        },
        {
            "op": "add-edge",
            "source": "setVendorContext",
            "sourcePort": "success",
            "target": "complianceReview",
            "targetPort": "input"
        },
        {
            "op": "add-edge",
            "source": "complianceReview",
            "sourcePort": "completed",
            "target": "approvalDecision",
            "targetPort": "input"
        },
        {
            "op": "add-edge",
            "source": "approvalDecision",
            "sourcePort": "true",
            "target": "onboardVendor",
            "targetPort": "input"
        },
        {
            "op": "add-edge",
            "source": "onboardVendor",
            "sourcePort": "success",
            "target": "endApproved",
            "targetPort": "input"
        },
        {
            "op": "add-edge",
            "source": "approvalDecision",
            "sourcePort": "false",
            "target": "rejectVendor",
            "targetPort": "input"
        },
        {
